ON CONFLICT (id) DO UPDATE
  SET display_id = EXCLUDED.display_id,
      title = EXCLUDED.title,
      summary = EXCLUDED.summary,
      significance = EXCLUDED.significance,
      lead_team_id = EXCLUDED.lead_team_id,
      last_updated_by = EXCLUDED.last_updated_by,
      last_updated_date_time = EXCLUDED.last_updated_date_time,
      row_version = EXCLUDED.row_version;

ON CONFLICT (activity_id) DO UPDATE
  SET venue_name = EXCLUDED.venue_name,
      address_line1 = EXCLUDED.address_line1,
      city = EXCLUDED.city,
      province_or_state = EXCLUDED.province_or_state,
      country = EXCLUDED.country;

DELETE FROM activity_categories WHERE activity_id BETWEEN 1 AND 76;

SELECT g.id, ((g.id - 1) % 7) + 1, true, now()
FROM generate_series(1, 76) AS g(id);

;

;

ON CONFLICT (activity_id, user_id) DO NOTHING;
